import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"EgoVLA: Learning Vision-Language-Action Models from Egocentric Human Videos","description":"","frontmatter":{"title":"EgoVLA: Learning Vision-Language-Action Models from Egocentric Human Videos","arxiv":"2507.12440","date":"2025-07-16","authors":"Ruihan Yang, Qinxi Yu, Yecheng Wu, Rui Yan, Borui Li, An-Chieh Cheng, Xueyan Zou, Yunhao Fang, Xuxin Cheng, et al.","categories":"cs.RO, cs.AI, cs.CV, cs.LG","topics":"具身智能, 人类视频预训练, 灵巧操作","outline":[2,2]},"headers":[],"relativePath":"papers/2507.12440.md","filePath":"papers/2507.12440.md","lastUpdated":null}'),l={name:"papers/2507.12440.md"};function e(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="egovla-learning-vision-language-action-models-from-egocentric-human-videos" tabindex="-1">EgoVLA: Learning Vision-Language-Action Models from Egocentric Human Videos <a class="header-anchor" href="#egovla-learning-vision-language-action-models-from-egocentric-human-videos" aria-label="Permalink to &quot;EgoVLA: Learning Vision-Language-Action Models from Egocentric Human Videos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.12440" target="_blank" rel="noreferrer">2507.12440</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-16</td></tr><tr><td><strong>作者</strong></td><td>Ruihan Yang, Qinxi Yu, Yecheng Wu, Rui Yan, Borui Li, An-Chieh Cheng, Xueyan Zou, Yunhao Fang, Xuxin Cheng, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>把 VLA 的输出定义在 MANO 人手参数空间上，先用带手腕/手部姿态标注的第一人称人类视频预训练，再用少量机器人演示后训练，靠 IK 与指尖重定向把人手动作转成双臂人形机器人动作。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v3</strong> 全文（abs 页给出的 HTML 版本即 v3；v1/v2/v3 的文件大小完全一致，应为元数据修订）。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>模仿学习在机器人操作上的进展基本由真机数据量推动，而真机数据的采集必须占用一台机器人和一名熟练操作员。这条约束是乘法性的：想把数据量提高一个数量级，就要把机器人数量和操作员工时同时提高一个数量级。作者把这句话推到极端：如果把人当成一种特殊的机器人，世界上正在同时运行的&quot;机器人&quot;有 80 亿台，而且它们出现在所有我们希望机器人进入的场景里——包括机器人现在根本放不进去、或者遥操作根本做不了的场景。</p><p>问题因此变成：能不能直接在第一人称人类视频上训练一个 VLA，让它输出人的手腕位姿与手指关节，再通过几何变换把这套动作换成机器人动作？如果可行，数据的瓶颈就从&quot;有多少台机器人&quot;变成&quot;有多少段带手部姿态标注的视频&quot;，而后者随 Quest 3、Vision Pro、Aria 这类设备的普及正在快速变便宜。这篇论文给出的答案是有条件的可行：人类预训练确实带来显著增益，但它<strong>不能</strong>免除对机器人演示的需求。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>最直接的对照是众包真机数据路线。Open X-Embodiment 与 DROID 把几十个实验室的轨迹汇总起来训练 Octo、OpenVLA 这类通用策略，但它们的规模上限仍由硬件决定，且任务分布高度偏向桌面抓放。遥操作侧的工作（关节映射、外骨骼 AirExo/ACE、VR 的 Open-TeleVision/Bunny-VisionPro）降低了单条轨迹的成本，却没有改变&quot;每条轨迹都要一台机器人&quot;这个结构。</p><p>从人类视频学习的路线此前主要停在<strong>表征</strong>层面：R3M 式的对比学习、掩码自编码器、以及各种从 in-the-wild 视频里抽 affordance 或交互线索的方法。这些工作证明了正迁移存在，但学到的是视觉编码器，动作头仍要从机器人数据从零训。为什么细粒度的手部/手腕姿态没有被直接当作监督信号？论文给出的理由有两层：其一，早期第一人称数据集（EPIC-Kitchens、Ego4D 一类）缺少可靠的 3D 手部与相机位姿标注；其二，第一人称视频的相机一直在动，直接回归相机系下的未来手腕位置会得到自相矛盾的监督。前者随 HOT3D、HOI4D、TACO 这类带标注数据集的出现被缓解，后者需要一个显式的坐标处理，正是本文动手的地方。HOI-forecast 一类工作已经能预测长时程人类操作意图，但它的输出不是可执行的控制量。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>一个认真的研究者在 2024 年底大概会这样推进。第一步是观察到人手与目前主流的灵巧手（Inspire、Allegro、LEAP）在运动学拓扑上高度相似：都是五指、都靠腕部六自由度定位。第二步是注意到 MANO 提供了一个可微的、低维的（15 维 PCA 就能覆盖大部分手型）人手参数化，而且已经是手部重建社区的事实标准——这意味着人类视频侧的标注和机器人侧的重定向可以共用一套坐标。第三步是发现&quot;机器人手 → MANO&quot;这个方向可以被写成一个小的优化问题：找一组 MANO 参数，使其前向运动学给出的指尖位置与机器人指尖位置一致。既然两边都能投影到同一个 MANO 空间，那么模型的输出层就不必区分数据来自人还是机器人。</p><p>第四步是处理第一人称视频的相机运动。既然数据集提供世界系相机位姿，就可以把未来的手腕位置先转到世界系、再投影回<strong>当前帧</strong>的相机系，从而让&quot;未来 1 秒的手腕在哪里&quot;这个监督信号与当前观测严格对齐。到这一步，一个标准的 VLM + 动作头架构就可以直接吃人类视频了，剩下的只是数据配比与后训练的工程问题。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>人和灵巧手的差别，在动作层面可以被一组固定的几何变换吃掉：腕部位姿差一个刚体变换加逆运动学，手指差一个&quot;指尖对齐&quot;的重定向。只要把 VLA 的输出空间从&quot;机器人关节角&quot;换成&quot;MANO 参数&quot;，人类视频就自动变成了合法的动作监督，而不再只是视觉预训练语料。剩下的差异——外观、相机高度、手的形状——则是<strong>视觉</strong>上的差异，需要少量真机数据来对齐。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以基准里的 Stack-Can（把易拉罐叠到碟子上）为例走一遍。</p><p><strong>输入</strong>：6 帧第一人称 RGB（当前帧加前 5 帧，间隔 0.2 秒，覆盖 1 秒历史，各 384×384），一条即时指令（描述当下要做的动作而非高层规划），以及本体感知（双手腕平移/旋转 + 手部姿态参数，经 MLP 编码）。</p><p><strong>主干</strong>：NVILA-2B 作为 VLM 骨干。作者取词表最后 30 个 word ID 当作 action query token 送进去，把对应的隐层送入动作头。</p><p><strong>动作头</strong>：一个 300M 的 transformer（6 层 encoder，隐藏维 1536），吃本体感知与 query token 的隐层，输出双手各 30 步（1 秒 @30 Hz）的动作。每一步动作 = 相机系下的腕部平移（3 维）+ 旋转（rot6D 表示）+ 手部关节（MANO 前 15 个 PCA 分量）。</p><p><strong>训练</strong>：先在人类数据上预训练 20 个 epoch，再在机器人演示上后训练 115 个 epoch（第 100 epoch 后降学习率），全模型包括视觉编码器一起微调。</p><p><strong>人类数据</strong>：四个来源混合——HOI4D（4,000 段单手操作）、HOT3D（833 分钟，33 个刚体，精确 3D 手/相机位姿）、HoloAssist（166 小时复杂双手任务，标注较噪，均匀下采样到 1/10 以免压过其他源）、TACO（2,317 段，151 个&quot;工具-动作-物体&quot;三元组）。按 3 FPS 采样，共约 50 万对图像-动作。</p><p><strong>部署</strong>：预测出的腕部位姿经 3D 变换转成机器人末端位姿，再用 IK 解出手臂关节角；预测出的 MANO 参数经前向运动学算出 3D 手部关键点，再由一个轻量 MLP 映射成机器人手的关节指令。这个 MLP 在机器人演示上训练，平均指尖位置误差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span> 米。</p><p><strong>评测平台</strong>：作者自建 Ego Humanoid Manipulation Benchmark（Isaac Lab，Unitree H1 + 双 Inspire 手，36 维动作空间，30 Hz），12 个任务分短时程原子动作（Push-Box、Flip-Mug、Pour-Balls、Open/Close-Drawer、Open-Laptop、Stack-Can）与长时程组合任务（Sort-Cans、Insert-Cans、Unload-Cans、Insert-And-Unload-Cans、Stack-Can-Into-Drawer），每任务 100 条 VR 遥操作演示（OpenTelevision + Meta Quest 3）。5 种房间贴图 × 5 种桌面贴图 = 25 种视觉配置，训练只用其中 3 种，剩下 22 种作为未见配置。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>训练目标是三项加权回归损失：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">wrist trans</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">wrist trans</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">wrist rot</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">wrist rot</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">joint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">joint</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>其中平移与关节角用 L2，旋转项作用在 rot6D 表示上。用 rot6D 而非四元数或轴角，是因为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord">3</span><span class="mclose">)</span></span></span></span> 到任何三维或四维紧致参数化的映射都不连续，回归时会在参数边界处产生大梯度；rot6D 通过&quot;取旋转矩阵前两列 + Gram-Schmidt 正交化&quot;给出一个连续满射，对回归友好。</p><p>把机器人手投影到 MANO 空间的那一步是一个小优化问题：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.4963em;vertical-align:-0.7463em;"></span><span class="mord"><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.3537em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">Θ</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop"><span class="mord text"><span class="mord">minimize</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7463em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord mathcal">L</span><span class="mopen">(</span><span class="mord mathbf">Θ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.0788em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">5</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">SmoothL1</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathbf">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathbf">Θ</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">obs</span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7252em;vertical-align:-0.0391em;"></span><span class="mord mathbf">Θ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">15</span></span></span></span></span></span></span></span></span></span></span></span> 是 MANO 的 PCA 系数，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9722em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbf">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是 MANO 前向运动学给出的五个指尖位置，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">J</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">obs</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">5</span><span class="mbin mtight">×</span><span class="mord mtight">3</span></span></span></span></span></span></span></span></span></span></span></span> 是机器人手的实测指尖位置。这个式子的直觉是：不要求两只手&quot;长得像&quot;，只要求<strong>指尖落在同一处</strong>——因为对绝大多数抓取而言，任务成败由指尖接触点决定，掌骨怎么摆并不重要。这也解释了为什么只对齐 5 个点就够，以及为什么误差能压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span> 米量级。</p><p>这套形式化只保证了<strong>运动学</strong>层面的一致，它不包含任何力、摩擦或接触动力学项。§ 9 会回到这一点。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：不做机器人后训练，纯人类预训练的模型能直接开机器人吗？</strong> 作者直接给出否定答案：零样本部署在所有任务上成功率均为 <strong>0%</strong>，连 Pour-Balls 这种预训练里见过的任务也不行。这是全文最有价值的一个负结果，它把&quot;统一动作空间&quot;的适用范围钉死在了&quot;可以共享输出层&quot;，而不是&quot;可以免训练迁移&quot;。</p><p><strong>问题二：人类预训练对域内性能有多大帮助？</strong> 在见过的视觉配置下，短时程任务平均成功率/进度率：ACT 专家模型 24.87 / 59.79，EgoVLA-NoPretrain 64.55 / 71.87，EgoVLA 77.78 / 84.92。长时程任务：ACT 2.22 / 26.47，NoPretrain 26.67 / 54.93，EgoVLA 45.93 / 80.78。长时程上的差距（约 19 个百分点）明显大于短时程，符合&quot;预训练提供的是与具身无关的通用手部技能，因而在需要串联多个技能时收益更大&quot;的解释。不过逐任务看并非全胜：Pour-Balls 上 NoPretrain 的 85.19 反而<strong>高于</strong> EgoVLA 的 77.78，而 Pour-Balls 恰是作者点名的&quot;预训练见过的任务&quot;；Open-Drawer 两者持平（59.26）。</p><p><strong>问题三：预训练是否改善视觉泛化？</strong> 换到 22 种未见背景后，EgoVLA 短时程平均从 77.78 掉到 69.11（降 8.67 点），NoPretrain 从 64.55 掉到 51.28（降 13.27 点）。正文把后者概括为&quot;23% 的下降&quot;，但按表 1 算相对降幅是 20.6%、绝对降幅是 13.3 点，与 23% 都对不上。长时程上 EgoVLA 未见配置成功率 28.79，作者称进度率&quot;基本保持&quot;，而表 2 里进度率其实从 80.78 降到 69.11（降 11.7 点），这句概括偏乐观。</p><p><strong>问题四：预训练能替代多少机器人数据？</strong> EgoVLA(50%) 只用一半机器人演示：短时程 48.15、长时程 7.41。这两个数字<strong>都低于</strong>使用全量机器人数据但完全没有人类预训练的 NoPretrain（64.55 / 26.67）。换句话说，在这个基准上，人类视频预训练并不能补偿机器人演示的减半。</p><p>数据配比消融（图 7，无数值表）显示增加人类数据的规模与多样性单调改善未见背景下的表现，且即使 HoloAssist 标注噪、HOT3D 缺语言标签、TACO 视觉多样性低，也都呈现正迁移。</p><p>评测规模：见过配置每任务 27 次 rollout（3 背景 × 9 次），未见配置 66 次（22 背景 × 3 次），物体初始位置在最大 20 cm × 20 cm 的范围内随机，且落在训练未覆盖的区域。3.70% 这类数值即 1/27，说明分辨率相当粗。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：EgoVLA 把 VLA 的动作空间定义在 MANO 人手参数上，使第一人称人类视频直接成为动作监督而非仅仅是视觉预训练语料。人机之间的差异用刚体变换 + IK + 指尖对齐的重定向吃掉，指尖对齐误差可压到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span> 米。在自建的 Isaac Lab 人形双臂基准上，人类预训练使短时程成功率从 64.55 提到 77.78、长时程从 26.67 提到 45.93，未见背景下的退化也明显更小。但纯人类预训练零样本部署成功率为 0%，且用一半机器人数据的 EgoVLA 反而不如用全量数据的无预训练版本。因此这套方法的正确定位是&quot;降低机器人数据的边际需求曲线的斜率&quot;，而不是&quot;替代机器人数据&quot;。</p><p><strong>3 句版</strong>：把 VLA 输出改写成 MANO 参数，人类视频就变成合法的动作数据；预训练在长时程与视觉泛化上收益最大；但机器人后训练仍不可省，且数据减半时预训练补不回来。</p><p><strong>1 句版</strong>：人手是灵巧手的超集，所以人类视频可以当动作数据用——前提是你仍然有足够的真机演示来对齐视觉。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>人与机器人的动作空间差异可以被一组固定的几何变换充分近似</strong>。整篇方法都建立在这句话上——统一动作空间、IK、指尖重定向、乃至&quot;预训练学到的技能可以直接复用&quot;，全都以此为前提。</p><p>这个假设在实践中很可能不成立，因为它只覆盖运动学而完全不覆盖动力学。MANO 优化目标里只有指尖位置，没有接触力、摩擦系数、手指刚度或负载；Inspire 手的 6 个主动自由度与人手 20 余个自由度的可达工作空间也不同构，重定向必然在部分构型上产生不可忽略的投影误差。论文自己提供了这个假设失效的最强证据：零样本成功率是 0%，而且作者把原因归为&quot;外观、感知与运动学三方面的失配&quot;——运动学赫然在列。另一处证据是 EgoVLA(50%) 的崩塌：如果几何变换真的把差异吃干净了，人类先验应当能在机器人数据变少时顶上，而实际结果相反。</p><p>论文为该假设提供的正面证据只有两条：指尖重定向误差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span> 米，以及&quot;把原始演示经重定向流水线回放仍能完成任务&quot;。前者只度量了一个静态映射的精度，后者是开环回放、不涉及闭环误差累积，都不足以支撑&quot;技能可迁移&quot;。缺的是一个直接测量：把人类视频里的动作经完整流水线投到机器人上执行，统计成功率。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证，目标是把&quot;动作先验&quot;与&quot;视觉表征&quot;这两个可能的增益来源分开。</p><ul><li><strong>数据</strong>：HOI4D 的公开子集（约 4,000 段，自带手部姿态）作为人类侧；LIBERO 或任意一个自带演示的仿真操作套件（每任务 50 条）作为机器人侧。不需要人形机器人，单臂加二指夹爪即可，把 MANO 的手指维度退化成一维开合。</li><li><strong>实现</strong>：一个小 VLM（例如 2B 级）+ 三层 MLP 动作头，输出腕位姿 + 一维夹爪。三个训练配置：(a) 无预训练；(b) 在 HOI4D 上按本文方式预训练；(c) 在 HOI4D 上预训练但<strong>把动作标签在样本间随机打乱</strong>，只保留&quot;看这些图像&quot;这一件事。</li><li><strong>测量</strong>：三者在机器人后训练后的成功率，以及在未见背景（换贴图或加干扰物）下的成功率。</li><li><strong>判据</strong>：若 (b) 显著优于 (c)，说明动作先验本身有效，本文的核心叙事成立；若 (b) ≈ (c)，说明增益主要来自&quot;看了大量以手为中心的第一人称图像&quot;，即一种视觉域适配，那么用更便宜的自监督预训练即可获得同样收益。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，可以给出一个对全部结果都成立的替代解释：<strong>EgoVLA 的增益来自视觉表征的域适配，而非动作层面的技能迁移。</strong></p><p>支持这一解释的现成证据有三条，全部来自论文自己的表格。第一，EgoVLA(50%) 在短时程上只有 48.15，低于零人类预训练但用满机器人数据的 64.55——如果学到的是可复用的&quot;手部操作技能&quot;，它应当在数据稀缺时最有价值，而实际上它最没价值的时候恰恰就是数据稀缺时。第二，预训练带来的最大收益出现在<strong>未见背景</strong>上（退化幅度 8.67 点 vs 13.27 点），这正是视觉域适配最该产生效果的地方。第三，Pour-Balls 是论文点名的&quot;预训练里出现过的任务&quot;，而 EgoVLA 在它上面反而输给 NoPretrain 7.4 个百分点；如果是技能迁移，这个任务应当是收益最大的。</p><p>要证伪这一替代解释，需要 § 10 里的 (c) 组对照，或者一个更强的版本：把人类预训练目标换成&quot;预测被遮挡的图像块&quot;（纯视觉自监督），保持数据、算力、架构完全一致。论文没有做任何一个这样的对照，因此&quot;人类动作先验&quot;这一归因目前只是相关性证据。</p><p>另一个可预测的失败场景是：把评测从&quot;物体位置随机 20 cm × 20 cm 的桌面任务&quot;换成需要力控的任务（拧瓶盖、插销、擦拭）。此时运动学重定向的假设直接失效，预期 EgoVLA 相对 NoPretrain 的优势会消失甚至反转。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>局限驱动</strong>：本文把&quot;人 → 机器人&quot;处理成一个<strong>固定</strong>的、离线标定好的几何映射，而所有证据都指向这个映射本身才是瓶颈（零样本 0%、数据减半即崩）。既然映射固定，模型就必须靠机器人数据把映射误差&quot;背下来&quot;，这解释了为什么后训练不可省。</p><p><strong>新的 framing</strong>：不要把重定向当作预处理，而把它当成一个<strong>待辨识的、依赖构型的算子</strong>，并用机器人自身的执行结果来在线辨识它。具体地，把人到机器人的映射参数化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2542em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">ψ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span></span></span></span> 是一小组可学习参数（例如腕部偏置、指尖对齐权重、每根手指的增益），然后用&quot;策略在机器人上执行 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.2542em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">ψ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">human</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的结果&quot;作为反馈去更新 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span></span></span></span>，而策略本身保持冻结。这把问题从&quot;用真机数据修策略&quot;变成&quot;用真机数据修映射&quot;——后者的参数量小 2–3 个数量级，因此所需的真机数据也应当小 2–3 个数量级。</p><p><strong>可借鉴的相邻工具</strong>：系统辨识与 sim-to-real 里的&quot;delta action&quot;思路（用少量真机轨迹辨识一个作用在动作上的残差算子），以及 domain adaptation 里的 test-time adaptation。两者都已经证明&quot;只修接口、不修主干&quot;在数据极稀缺时优于端到端微调。</p><p><strong>第一个实验</strong>：固定 EgoVLA 的人类预训练权重完全不动，只用 10 条机器人演示辨识 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span></span></span></span>（相对 100 条演示的全模型后训练）。若 10 条 + 映射辨识能达到 100 条 + 全微调的一半以上成功率，就证明瓶颈确实在接口而非策略，进而说明&quot;零样本 0%&quot;是一个可以被廉价修复的工程问题，而不是范式的根本限制。</p>',60)])])}const u=a(l,[["render",e]]);export{h as __pageData,u as default};
